paginas.codigo:
.catalogo {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 80px;
  gap: 10px;
}

.destacado {
  grid-column: span 2;
}

.pagina {
  display: grid;
  grid-template-columns: 180px 1fr;
  grid-template-areas:
    "cabecera cabecera"
    "menu     contenido"
    "pie      pie";
}

header { grid-area: cabecera; }
nav    { grid-area: menu; }
main   { grid-area: contenido; }
footer { grid-area: pie; }
